INSERT INTO `cartas` (`categoria_id`, `qid`, `resposta`, `resposta_normalizada`, `url_fonte`, `resumo_fonte`, `status`) SELECT `id`, 'Q208460', '1984', '1984', 'https://pt.wikipedia.org/wiki/1984_(livro)', 'Mil novecentos e oitenta e quatro é um romance distópico do escritor inglês George Orwell. Foi publicado em 8 de junho de 1949 pela Secker & Warburg como o nono e último livro de Orwell concluído em vida. Tematicamente, centra-se nas consequências do totalitarismo, da vigilância em massa e da lavagem cerebral na sociedade. Orwell, um socialista democrático, modelou o Estado autoritário descrito no romance com base na União Soviética stalinista e na Alemanha Nazista. De forma mais ampla, o romance examina o papel da verdade e dos fatos nas sociedades e as formas como eles podem ser manipulados.', 'aprovada' FROM `categorias` WHERE `chave` = 'coisa';
INSERT INTO `dicas` (`carta_id`, `numero`, `texto`, `texto_normalizado`, `dificuldade`, `propriedade_origem`) VALUES (@carta, 1, 'Foi publicado em 8 de junho de 1949 pela Secker & Warburg como o nono e último livro de Orwell concluído em vida.', 'foi publicado em 8 de junho de 1949 pela secker warburg como o nono e ultimo livro de orwell concluido em vida', 'media', 'resumo_wikipedia_1');
