INSERT INTO `cartas` (`categoria_id`, `qid`, `resposta`, `resposta_normalizada`, `url_fonte`, `resumo_fonte`, `status`) SELECT `id`, 'Q24871', 'Avatar', 'avatar', 'https://pt.wikipedia.org/wiki/Avatar_(filme)', 'Avatar é um filme épico de ficção científica norte-americana de 2009, escrito e dirigido por James Cameron, e estrelado por Sam Worthington, Zoë Saldaña, Michelle Rodriguez, Sigourney Weaver e Stephen Lang. O filme, que foi produzido pela Lightstorm Entertainment e distribuído pela 20th Century Fox, tem seu enredo localizado no ano 2154 e é baseado em um conflito em Pandora, uma das luas de Polifemo, um dos três planetas gasosos fictícios que orbitam o sistema Alpha Centauri. Em Pandora, os colonizadores humanos e os Na\'vi, nativos humanoides, entram em guerra pelos recursos naturais do planeta e pela continuação da existência da espécie nativa. O título do filme refere-se aos corpos híbridos feitos a partir do ADN/DNA misturado de humanos e Na\'vi, criados por um grupo de cientistas através de engenharia genética, para interagir com os nativos de Pandora.', 'aprovada' FROM `categorias` WHERE `chave` = 'coisa';
