INSERT INTO `cartas` (`categoria_id`, `qid`, `resposta`, `resposta_normalizada`, `url_fonte`, `resumo_fonte`, `status`) SELECT `id`, 'Q480', 'Dom Quixote', 'dom quixote', 'https://pt.wikipedia.org/wiki/Dom_Quixote', 'Don Quixote, cujo título completo é O Engenhoso Fidalgo Dom Quixote da Mancha, é um romance espanhol de Miguel de Cervantes. Publicado originalmente em duas partes, em 1605 e 1615, o romance é considerado uma obra fundadora da Literatura ocidental e o primeiro romance moderno. O romance foi classificado por muitos autores conhecidos como o \"melhor romance de todos os tempos\" e a \"obra melhor e mais central na literatura mundial\". Dom Quixote é também um dos livros mais traduzidos do mundo e um dos romances mais vendidos de todos os tempos. O romance é uma sátira aos romances de cavalaria e às convenções literárias da época.', 'aprovada' FROM `categorias` WHERE `chave` = 'coisa';
INSERT INTO `dicas` (`carta_id`, `numero`, `texto`, `texto_normalizado`, `dificuldade`, `propriedade_origem`) VALUES (@carta, 1, 'O romance foi classificado por muitos autores conhecidos como o \"melhor romance de todos os tempos\" e a \"obra melhor e mais central na literatura mundial\".', 'o romance foi classificado por muitos autores conhecidos como o melhor romance de todos os tempos e a obra melhor e mais central na literatura mundial', 'media', 'resumo_wikipedia_2');
