INSERT INTO `cartas` (`categoria_id`, `qid`, `resposta`, `resposta_normalizada`, `url_fonte`, `resumo_fonte`, `status`) SELECT `id`, 'Q44578', 'Titanic', 'titanic', 'https://pt.wikipedia.org/wiki/Titanic_(filme_de_1997)', 'Titanic é um filme épico de romance e drama norte-americano de 1997, escrito, dirigido, co-produzido e co-editado por James Cameron. É uma história de ficção do naufrágio real do RMS Titanic, estrelando Leonardo DiCaprio como Jack Dawson, e Kate Winslet como Rose DeWitt Bukater, membros de diferentes classes sociais que se apaixonam durante a fatídica viagem inaugural do navio, saindo de Southampton para Nova Iorque em 10 de abril de 1912. Apesar dos personagens principais serem fictícios, alguns personagens são figuras históricas. Gloria Stuart interpreta Rose idosa, que narra o filme, enquanto Billy Zane interpreta Cal Hockley, o arrogante noivo rico da jovem Rose. Cameron viu a história de amor como um jeito de cativar o público para o desastre real.', 'aprovada' FROM `categorias` WHERE `chave` = 'coisa';
