INSERT INTO `cartas` (`categoria_id`, `qid`, `resposta`, `resposta_normalizada`, `url_fonte`, `resumo_fonte`, `status`) SELECT `id`, 'Q687', 'Molière', 'moliere', 'https://pt.wikipedia.org/wiki/Moli%C3%A8re', 'Jean-Baptiste Poquelin, mais conhecido como Molière, foi um dramaturgo, ator e encenador francês, considerado um dos mestres da comédia satírica. Teve um papel de destaque na dramaturgia francesa, até então muito dependente da temática da mitologia grega. Molière usou as suas obras para criticar os costumes da época. Como encenador, ficou também conhecido pelo seu rigor e meticulosidade.', 'aprovada' FROM `categorias` WHERE `chave` = 'pessoa';
