INSERT INTO `cartas` (`categoria_id`, `qid`, `resposta`, `resposta_normalizada`, `url_fonte`, `resumo_fonte`, `status`) SELECT `id`, 'Q5812', 'Novak Đoković', 'novak dokovic', 'https://pt.wikipedia.org/wiki/Novak_Djokovic', 'Novak Djokovic é um tenista profissional sérvio. Ele foi classificado como o número 1 do mundo em simples da ATP por um período recorde de 428 semanas, terminou o ano como número 1 em oito temporadas (recorde) e foi ranqueado como número 1 pelo menos uma vez em treze anos diferentes. Djokovic conquistou cem títulos de simples em nível de ATP Tour, incluindo um recorde de 24 torneios de Grand Slam, 40 Masters 1000 (recorde), sete finais de fim de ano (recorde) e uma medalha de ouro olímpica. Djokovic é o único homem na história do tênis a ser campeão vigente dos quatro majors ao mesmo tempo em três superfícies diferentes. Em simples, ele é o único homem a conquistar três vezes o Career Grand Slam, e o único jogador a completar um Career Golden Masters — feito que realizou duas vezes. Djokovic é o único jogador em simples a ter vencido todos os “Big Titles” ao longo da carreira.', 'aprovada' FROM `categorias` WHERE `chave` = 'pessoa';
