INSERT INTO `cartas` (`categoria_id`, `qid`, `resposta`, `resposta_normalizada`, `url_fonte`, `resumo_fonte`, `status`) SELECT `id`, 'Q1394', 'Vladimir Lenine', 'vladimir lenine', 'https://pt.wikipedia.org/wiki/Lenin', 'Vladimir Ilyich Ulianov, mais conhecido pelo pseudônimo Lenin (português brasileiro) ou Lenine (português europeu), foi um revolucionário comunista, político e teórico político russo que serviu como chefe de governo da Rússia Soviética de 1917 a 1924 e da União Soviética de 1922 até sua morte. Sob sua administração, a Rússia e em seguida a União Soviética tornaram-se um Estado socialista unipartidário governado pelo Partido Comunista (PCUS). Ideologicamente marxistas, suas teorias políticas são conhecidas como leninismo.', 'aprovada' FROM `categorias` WHERE `chave` = 'pessoa';
